import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';
import { Transform } from 'class-transformer';
import {
  IsInt,
  IsNumber,
  IsOptional,
  IsString,
  IsUUID,
  Length,
  Matches,
  Max,
  MaxLength,
  Min,
} from 'class-validator';
import {
  SIGN_CODE_MAX_LENGTH,
  SIGN_CODE_PATTERN,
} from '../../common/sign-code';

export class CreateEvaluationDto {
  @ApiProperty({
    format: 'uuid',
    description:
      'UUID v4 generated by Unity. When retrying a failed submission, reuse the same one.',
  })
  @IsUUID('4')
  attemptId: string;

  @ApiProperty({
    example: 'A',
    description: "Catalog code, e.g. 'A', 'Ñ', 'numeros.5', 'MONTH_JANUARY'.",
  })
  @Transform(({ value }) => (typeof value === 'string' ? value.trim() : value))
  @IsString()
  @Length(1, SIGN_CODE_MAX_LENGTH)
  @Matches(SIGN_CODE_PATTERN, {
    message: 'signCode may only contain letters, digits, underscores and dots',
  })
  signCode: string;

  @ApiProperty({
    minimum: 0,
    maximum: 100,
    example: 82,
    description: 'Similarity on a 0–100 scale, at most 2 decimals.',
  })
  @IsNumber({ allowNaN: false, allowInfinity: false, maxDecimalPlaces: 2 })
  @Min(0)
  @Max(100)
  precision: number;

  @ApiProperty({ minimum: 0, maximum: 3, example: 2 })
  @IsInt()
  @Min(0)
  @Max(3)
  stars: number;

  @ApiProperty({ minimum: 0, example: 20 })
  @IsInt()
  @Min(0)
  xp: number;

  @ApiPropertyOptional({ minimum: 0, example: 4200 })
  @IsOptional()
  @IsInt()
  @Min(0)
  durationMs?: number;

  @ApiPropertyOptional({ maxLength: 500 })
  @IsOptional()
  @IsString()
  @MaxLength(500)
  feedback?: string;
}
